import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.CVt6dz2a.js";const q=JSON.parse('{"title":"EP.29 用一行代码种出一座城","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.29-grow-a-city.md","filePath":"comics/EP.29-grow-a-city.md","lastUpdated":1793881879000}'),o={name:"comics/EP.29-grow-a-city.md"};function l(i,t,s,c,h,n){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="ep-29-用一行代码种出一座城" tabindex="-1">EP.29 用一行代码种出一座城 <a class="header-anchor" href="#ep-29-用一行代码种出一座城" aria-label="Permalink to &quot;EP.29 用一行代码种出一座城&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/29-procedural-modeling/basics">29.1 基础入门：程序化几何与噪声</a> 延伸阅读：<a href="./../guide/29-procedural-modeling/advanced">29.2 进阶应用：参数化建模与生长规则</a> · <a href="./../guide/29-procedural-modeling/practice">29.3 实战案例：程序化城市生成器</a> 动手演示：<a href="./../public/demos/procedural-modeling/geometry-recipes-lab.html">geometry-recipes-lab 程序化几何配方台</a> · <a href="./../public/demos/procedural-modeling/parametric-tree-lab.html">parametric-tree-lab 参数化生长树</a> · <a href="./../public/demos/procedural-modeling/city-generator-lab.html">city-generator-lab 程序化城市生成器</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱手工摆了 300 栋楼，需求方一句&quot;密度再高一点&quot;就要全城重摆；标签君手里的 40 个模型已经让包体涨到 18 MB。</td></tr><tr><td>② 揭秘</td><td>码叔把城市拆成四段流水线：地块划分 → 建筑体块 → 街道绿化 → 合并实例化；生成器是纯函数，参数进、几何出。</td></tr><tr><td>③ 实证</td><td>同一座城分别用&quot;每楼一 Mesh&quot;与&quot;实例 + 合并&quot;输出，draw call 从 300 降到 9，三角形数几乎不变；同一个 seed 刷新十次都是同一座城。</td></tr><tr><td>④ 结案</td><td>种子管复现、参数管风格、预算管性能；把配置写成 JSON，城市就从&quot;一次性作品&quot;变成&quot;可复现的输入&quot;。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-手摆的边界-数量与变化" tabindex="-1">① 手摆的边界：数量与变化 <a class="header-anchor" href="#_1-手摆的边界-数量与变化" aria-label="Permalink to &quot;① 手摆的边界：数量与变化&quot;">​</a></h3><p>一栋楼、一棵树，手工摆放没有问题。但城市有两个特征会迅速击穿手工方案：<strong>数量</strong>（几百上千栋楼）与<strong>变化</strong>（改一个密度、换一种风格就要整体重来）。</p><p>手工摆放的资产还有一个隐性成本：每一栋楼都是一份独立的顶点数据。40 个楼模型听起来不多，但每个都带完整 UV 与法线，包体很快就到十几 MB。程序化的思路是把&quot;模型&quot;换成&quot;规则&quot;——代码只有几 KB，变体却是无限的。</p><p>这一步要先接受一个事实：<strong>程序化不是替代美术，而是接管&quot;数量 + 变化&quot;</strong>。需要设计感的近景主角仍然交给建模软件；需要成片出现、需要按参数整批调整的物体，交给生成器。</p><h3 id="_2-流水线-数据先行-渲染后置" tabindex="-1">② 流水线：数据先行，渲染后置 <a class="header-anchor" href="#_2-流水线-数据先行-渲染后置" aria-label="Permalink to &quot;② 流水线：数据先行，渲染后置&quot;">​</a></h3><p>程序化城市的四个阶段各自只做一件事：</p><table tabindex="0"><thead><tr><th>阶段</th><th>输入</th><th>输出</th><th>实现要点</th></tr></thead><tbody><tr><td>地块划分</td><td>城市尺寸、地块尺寸、密度、seed</td><td>地块列表</td><td>网格 + 格内抖动，保留街区感</td></tr><tr><td>建筑体块</td><td>地块、风格、最高层数</td><td>楼块列表</td><td>覆盖率、退台、屋顶类型</td></tr><tr><td>街道绿化</td><td>地块网格、空地块</td><td>合并路带、实例化路灯与树</td><td>静态的合并，重复的实例化</td></tr><tr><td>合并实例化</td><td>全部列表</td><td>少量 draw call</td><td>按&quot;动不动&quot;分层，而不是按数量</td></tr></tbody></table><p>关键在&quot;<strong>数据先行</strong>&quot;：地块、楼块、窗格先生成成普通数组，渲染层再决定怎么画。这样同一份数据可以换三种输出（逐 Mesh、合并、实例化），也可以在生成完再统计&quot;建筑数 / 体块数 / 三角数&quot;。</p><p>生成器本身要遵守纯函数约定：参数进、几何出，不依赖时间、屏幕尺寸与 <code>Math.random()</code>。纯函数带来三个直接收益——可单测、可复现、可放进 Web Worker。</p><h3 id="_3-实证-draw-call-才是先掉的那根梁" tabindex="-1">③ 实证：draw call 才是先掉的那根梁 <a class="header-anchor" href="#_3-实证-draw-call-才是先掉的那根梁" aria-label="Permalink to &quot;③ 实证：draw call 才是先掉的那根梁&quot;">​</a></h3><p>同一座城，两种画法：</p><table tabindex="0"><thead><tr><th>指标</th><th>每楼一 Mesh</th><th>实例 + 合并</th></tr></thead><tbody><tr><td>draw calls</td><td>约等于楼数（300+）</td><td>个位数到十几</td></tr><tr><td>三角形数</td><td>与楼数成正比</td><td>几乎相同</td></tr><tr><td>CPU 提交</td><td>每栋一次状态准备</td><td>每类一次提交</td></tr><tr><td>可编辑性</td><td>单栋可随意改</td><td>改单栋要改实例矩阵或重建</td></tr></tbody></table><p>很多人以为&quot;卡&quot;是三角形太多，实际先撑不住的往往是 CPU 的提交次数。300 栋楼、每栋 12 个三角形，几何量微不足道；但 300 次 draw call 的状态准备足以吃掉半帧预算。先砍 draw call，再谈三角数，这个顺序不能反。</p><p>同一 seed 的可复现性也要在实证里验证：刷新页面、换设备、改窗口大小，城市都应该一模一样。做不到，说明随机流里混进了环境量，或者 <code>Math.random()</code> 漏在了某个分支里。</p><h3 id="_4-结案-三条纪律与一份配置" tabindex="-1">④ 结案：三条纪律与一份配置 <a class="header-anchor" href="#_4-结案-三条纪律与一份配置" aria-label="Permalink to &quot;④ 结案：三条纪律与一份配置&quot;">​</a></h3><ul><li><strong>种子管复现</strong>：用 <code>mulberry32</code> 这类带种子的 PRNG，固定随机调用顺序，禁止 <code>Math.random()</code> 参与生成。</li><li><strong>参数管风格</strong>：密度、层数、地块尺寸、风格各自只影响一件事，互不越权；参数范围要做钳制，防止手改 JSON 把浏览器生成到卡死。</li><li><strong>预算管性能</strong>：建筑数、窗格数、实例数都要设硬上限；静态物体尽早合并，同构物体尽量实例化。</li></ul><p>把 <code>seed / density / maxFloors / lotSize / style</code> 收进一份带版本号的 JSON，城市就从&quot;一次性作品&quot;变成&quot;可复现的输入&quot;。分享一座城只需要复制一段配置，重建一座城只需要改一个 seed——这才是程序化建模真正的交付形态。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：每次刷新城市都不一样？</strong> 生成路径里混进了 <code>Math.random()</code>，或随机调用顺序被条件分支改变。固定种子 + 固定顺序 + 独立随机流。</li><li><strong>Q：draw call 比楼数还多？</strong> 楼块、屋顶、窗格、路灯各建一个 Mesh 就会翻倍。同构物体统一交给 InstancedMesh，静态路带合并。</li><li><strong>Q：窗格一多就卡死？</strong> 单栋楼 8 层 × 3 列 × 两面已接近 50 个实例，200 栋就是一万。设总实例预算，只铺两个立面。</li><li><strong>Q：合并几何返回 null？</strong> 参与合并的几何体属性结构不一致（缺 uv、索引状态不同）。统一属性后再合并。</li><li><strong>Q：配置改回读后 GUI 与场景不一致？</strong> 回读参数后没有刷新面板显示。调用 <code>controllersRecursive().updateDisplay()</code> 并重新生成。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>程序化建模相比传统模型资产的四个优势是什么？它不适合替代哪类资产？</li><li>城市生成流水线的四个阶段分别产出什么数据？为什么强调&quot;数据先行、渲染后置&quot;？</li><li>同一 seed 要得到同一座城，需要遵守哪三条纪律？如果只改密度却导致地标位置变化，问题出在哪？</li></ol><details><summary>答案</summary><ol><li>四个优势：制作成本低（写一次生成器批量产出）、变体多（改一个参数就是新版本）、包体小（只有代码没有大模型数据）、可复现可控（seed + 参数可版本化）。它不适合替代需要设计感的近景主角、精确造型道具这类资产——这些仍然应该由美术建模完成。</li><li>四阶段：① 地块划分产出地块列表；② 建筑体块产出楼块列表（位置、尺寸、颜色）；③ 街道绿化产出合并路带与实例化的路灯、树；④ 合并实例化把上述数据压成少量 draw call。强调数据先行，是因为渲染层可以晚一步决定&quot;逐 Mesh / 合并 / 实例化&quot;，同一份数据能换三种输出，也便于统计与导出配置。</li><li>三条纪律：不用 <code>Math.random()</code> 而用带种子 PRNG；固定随机调用顺序；不依赖时间、屏幕尺寸、设备像素比等环境量。只改密度却导致地标移动，是因为地标与地块共用同一条随机流——密度改变了每个格子的随机消耗数量，后续所有随机值整体错位。修法是给地标用独立种子，或先固定地标格再生成其它地块。</li></ol></details>',27)])])}const p=a(o,[["render",l]]);export{q as __pageData,p as default};
